window.SNAKE_AUDIO={};
window.SNAKE_SOUNDS={"eat":"data:audio/wav;base64,","wall":"data:audio/wav;base64,","click":"data:audio/wav;base64,","background":"data:audio/mpeg;base64,"};
(()=>{const pending=new Map();window.getSnakeWordAudio=async path=>{if(window.SNAKE_AUDIO[path])return window.SNAKE_AUDIO[path];const id=Number(path.match(/(\d+)\.mp3$/)?.[1]);if(!Number.isInteger(id)||id<0||id>=4544)throw Error('Unknown audio');const batch=Math.floor(id/400);if(!pending.has(batch)){pending.set(batch,new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='audio-pack-'+batch+'.js';const timer=setTimeout(()=>{script.remove();pending.delete(batch);reject(Error('Audio timeout'))},15000);script.onload=()=>{clearTimeout(timer);resolve()};script.onerror=()=>{clearTimeout(timer);pending.delete(batch);reject(Error('Audio loading failed'))};document.head.append(script)}))}await pending.get(batch);if(!window.SNAKE_AUDIO[path])throw Error('Audio missing');return window.SNAKE_AUDIO[path]}})();
